using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Diagnostics;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using ATAS.DataFeedsCore;
using ATAS.Indicators;
using ATAS.Strategies.Chart;

namespace AtasMt5ProbeStrategy
{
    /// <summary>
    /// Demo-only ATAS test executor. This is intentionally separate from the
    /// observation strategy: it accepts only three fixed commands generated by
    /// the local test service (open a distant limit, modify it, then cancel it).
    /// It is disabled by default and can act only on orders carrying its own
    /// AB2TEST run marker.
    /// </summary>
    [Category("Custom")]
    [DisplayName("AtasMt5TestDriver")]
    public sealed class AtasMt5TestDriverStrategy : ChartStrategy
    {
        private const string MarkerPrefix = "AB2TEST:";
        private ProbeWebSocketClient? _client;
        private string _sessionId = "";
        private long _eventSequence;
        private readonly object _outboxLock = new object();
        private Task _outboxTail = Task.CompletedTask;
        private readonly HashSet<string> _executedCommandIds = new HashSet<string>(StringComparer.Ordinal);
        private bool _disposed;

        [OFT.Attributes.ParameterAttribute]
        [DisplayName("Test driver WebSocket URL")]
        public string ServerUrl { get; set; } = "ws://127.0.0.1:8767";

        [OFT.Attributes.ParameterAttribute]
        [DisplayName("Enable demo test trading")]
        public bool EnableTestTrading { get; set; } = false;

        [OFT.Attributes.ParameterAttribute]
        [DisplayName("Test-control token")]
        public string TestControlToken { get; set; } = "";

        [OFT.Attributes.ParameterAttribute]
        [DisplayName("Maximum test quantity")]
        public decimal MaximumTestQuantity { get; set; } = 1m;

        [OFT.Attributes.ParameterAttribute]
        [DisplayName("Pending distance ticks")]
        public int PendingDistanceTicks { get; set; } = 100;

        [OFT.Attributes.ParameterAttribute]
        [DisplayName("Modify distance ticks")]
        public int ModifyDistanceTicks { get; set; } = 20;

        [OFT.Attributes.ParameterAttribute]
        [DisplayName("Test price step")]
        public decimal TestPriceStep { get; set; } = 0.1m;

        protected override void OnStarted()
        {
            _disposed = false;
            _sessionId = Guid.NewGuid().ToString("N");
            _eventSequence = 0;
            _executedCommandIds.Clear();
            _client = new ProbeWebSocketClient(ServerUrl);
            StrategyLog.Append($"Test driver started session={_sessionId}, enabled={EnableTestTrading}, server={ServerUrl}\n");
            Emit("test_driver_ready", new
            {
                enabled = EnableTestTrading,
                has_token = !string.IsNullOrWhiteSpace(TestControlToken),
                maximum_quantity = MaximumTestQuantity,
                pending_distance_ticks = PendingDistanceTicks,
                modify_distance_ticks = ModifyDistanceTicks,
            });
        }

        protected override void OnNewOrder(Order order)
        {
            if (IsOwnedTestOrder(order))
                EmitOrder(order);
        }

        protected override void OnOrderChanged(Order order)
        {
            if (IsOwnedTestOrder(order))
                EmitOrder(order);
        }

        protected override void OnOrderRegisterFailed(Order order, string error)
        {
            if (IsOwnedTestOrder(order))
                Emit("test_driver_error", new { operation = "open", order_id = order.Id ?? "", message = error ?? "" });
        }

        protected override void OnOrderModifyFailed(Order order, Order newOrder, string error)
        {
            if (IsOwnedTestOrder(order))
                Emit("test_driver_error", new { operation = "modify", order_id = order.Id ?? "", message = error ?? "" });
        }

        protected override void OnOrderCancelFailed(Order order, string error)
        {
            if (IsOwnedTestOrder(order))
                Emit("test_driver_error", new { operation = "cancel", order_id = order.Id ?? "", message = error ?? "" });
        }

        protected override void OnCalculate(int bar, decimal value)
        {
        }

        protected override void OnSuspended() => StopDriver();

        protected override void OnStopped() => StopDriver();

        private void EmitOrder(Order order)
        {
            Emit("order_changed", new
            {
                id = order.Id ?? "",
                state = order.State.ToString(),
                canceled = order.Canceled,
                comment = order.Comment ?? "",
                security = order.Security?.ToString() ?? "",
                direction = order.Direction.ToString(),
                order_type = order.Type.ToString(),
                price = order.Price,
                quantity_to_fill = order.QuantityToFill,
                unfilled = order.Unfilled,
            });
        }

        private void Emit(string eventType, object data)
        {
            var message = new ProbeEnvelope
            {
                SessionId = _sessionId,
                EventId = Interlocked.Increment(ref _eventSequence),
                EventType = eventType,
                SourceSymbol = Security?.ToString() ?? "TEST",
                AtasTimestampUtc = DateTimeOffset.UtcNow.ToString("O"),
                LocalMonotonicTicks = Stopwatch.GetTimestamp(),
                LocalStopwatchFrequency = Stopwatch.Frequency,
                DeliveryMode = "sync",
                Data = data,
            };
            lock (_outboxLock)
            {
                _outboxTail = _outboxTail
                    .ContinueWith(_ => SendEventAsync(message), CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.Default)
                    .Unwrap();
            }
        }

        private async Task SendEventAsync(ProbeEnvelope message)
        {
            while (!_disposed)
            {
                try
                {
                    if (_client == null || !await _client.EnsureConnectedAsync())
                        return;
                    var acknowledgement = await _client.SendAsync(message, true, 1000);
                    if (acknowledgement?.TestCommand != null)
                        await HandleTestCommandAsync(acknowledgement.TestCommand);
                    return;
                }
                catch (Exception error)
                {
                    StrategyLog.Append($"Test driver transport error event={message.EventId}: {error.Message}\n");
                    try
                    {
                        await Task.Delay(100);
                    }
                    catch
                    {
                        return;
                    }
                }
            }
        }

        private async Task HandleTestCommandAsync(ProbeTestCommand command)
        {
            if (string.IsNullOrWhiteSpace(command.CommandId) || !_executedCommandIds.Add(command.CommandId))
                return;
            if (!EnableTestTrading)
            {
                EmitReceipt(command, false, "Enable demo test trading is false");
                return;
            }
            if (string.IsNullOrWhiteSpace(TestControlToken) || !string.Equals(TestControlToken, command.Token, StringComparison.Ordinal))
            {
                EmitReceipt(command, false, "test-control token rejected");
                return;
            }
            try
            {
                switch (command.Command)
                {
                    case "open_pending":
                        await OpenPendingAsync(command);
                        break;
                    case "modify_pending":
                        await ModifyPendingAsync(command);
                        break;
                    case "cancel_pending":
                        await CancelPendingAsync(command);
                        break;
                    default:
                        throw new InvalidOperationException("unsupported test command");
                }
                EmitReceipt(command, true, "submitted to ATAS");
            }
            catch (Exception error)
            {
                StrategyLog.Append($"Test driver command failed command={command.Command}: {error.Message}\n");
                EmitReceipt(command, false, error.Message);
            }
        }

        private async Task OpenPendingAsync(ProbeTestCommand command)
        {
            ValidateTradingContext(command);
            if (BestBid == null)
                throw new InvalidOperationException("best bid is unavailable");
            var distance = Math.Max(1, PendingDistanceTicks) * ValidatedPriceStep();
            var order = new Order
            {
                Portfolio = Portfolio,
                Security = Security,
                Direction = OrderDirections.Buy,
                Type = OrderTypes.Limit,
                Price = BestBid.Price - distance,
                QuantityToFill = ValidatedQuantity(),
                Comment = Marker(command.RunId),
            };
            await OpenOrderAsync(order);
        }

        private async Task ModifyPendingAsync(ProbeTestCommand command)
        {
            var order = FindOwnedOrder(command);
            var distance = Math.Max(1, ModifyDistanceTicks) * ValidatedPriceStep();
            var newOrder = new Order
            {
                Portfolio = order.Portfolio,
                Security = order.Security,
                Direction = order.Direction,
                Type = order.Type,
                Price = order.Price - distance,
                TriggerPrice = order.TriggerPrice,
                TriggerPriceType = order.TriggerPriceType,
                QuantityToFill = order.QuantityToFill,
                Comment = order.Comment,
            };
            await ModifyOrderAsync(order, newOrder);
        }

        private async Task CancelPendingAsync(ProbeTestCommand command)
        {
            await CancelOrderAsync(FindOwnedOrder(command));
        }

        private Order FindOwnedOrder(ProbeTestCommand command)
        {
            if (string.IsNullOrWhiteSpace(command.SourceOrderId))
                throw new InvalidOperationException("source_order_id is required");
            var expectedMarker = Marker(command.RunId);
            var order = Orders.FirstOrDefault(candidate =>
                string.Equals(candidate.Id, command.SourceOrderId, StringComparison.Ordinal)
                && string.Equals(candidate.Comment, expectedMarker, StringComparison.Ordinal));
            return order ?? throw new InvalidOperationException("owned active test order was not found");
        }

        private void ValidateTradingContext(ProbeTestCommand command)
        {
            if (string.IsNullOrWhiteSpace(command.RunId) || Security == null || Portfolio == null)
                throw new InvalidOperationException("run ID, chart security, and portfolio are required");
            _ = ValidatedQuantity();
            _ = ValidatedPriceStep();
        }

        private decimal ValidatedQuantity()
        {
            if (MaximumTestQuantity <= 0m)
                throw new InvalidOperationException("maximum test quantity must be positive");
            return MaximumTestQuantity;
        }

        private decimal ValidatedPriceStep()
        {
            if (TestPriceStep <= 0m)
                throw new InvalidOperationException("test price step must be positive");
            return TestPriceStep;
        }

        private static string Marker(string runId) => MarkerPrefix + runId;

        private static bool IsOwnedTestOrder(Order order) =>
            !string.IsNullOrWhiteSpace(order.Comment) && order.Comment.StartsWith(MarkerPrefix, StringComparison.Ordinal);

        private void EmitReceipt(ProbeTestCommand command, bool accepted, string message)
        {
            Emit("test_command_receipt", new
            {
                run_id = command.RunId,
                command = command.Command,
                accepted,
                message,
            });
        }

        private void StopDriver()
        {
            if (_disposed)
                return;
            _disposed = true;
            _client?.Dispose();
            _client = null;
            StrategyLog.Append("Test driver stopped\n");
        }
    }
}
